import pikepdf

# Open the PDF
pdf = pikepdf.open('/root/sc100-blank.pdf')

def explore_fields(fields, prefix=""):
    """Recursively explore form fields"""
    if fields is None:
        return

    for field in fields:
        try:
            field_name = str(field.T) if hasattr(field, 'T') else "?"
            field_name = field_name.strip("'\"")
            field_type = str(field.FT) if hasattr(field, 'FT') else "unknown"
            field_type = field_type.strip("'\"")

            # Check if this is a parent field with children
            if hasattr(field, 'Kids') and field.Kids:
                print(f"{prefix}[GROUP] {field_name}")
                explore_fields(field.Kids, prefix + "  ")
            else:
                print(f"{prefix}{field_name} ({field_type})")
        except Exception as e:
            print(f"{prefix}[Error: {e}]")

if pdf.Root.AcroForm and pdf.Root.AcroForm.Fields:
    explore_fields(pdf.Root.AcroForm.Fields)
else:
    print("No form fields found")
