import pikepdf

# Open the original PDF to explore more carefully
pdf = pikepdf.open('/root/sc100-blank.pdf')

# Look for fields that might indicate claim type/basis
def explore_page3_fields(fields, prefix="", path=""):
    """Explore Page3 fields in detail"""
    if fields is None:
        return

    for i, field in enumerate(fields):
        try:
            field_name = str(field.T).strip("'\"") if hasattr(field, 'T') else ""
            field_type = str(field.FT).strip("'\"") if hasattr(field, 'FT') else ""

            current_path = f"{path}/{field_name}" if field_name else f"{path}/[group-{i}]"

            print(f"{prefix}{current_path} ({field_type})")

            if hasattr(field, 'Kids') and field.Kids:
                explore_page3_fields(field.Kids, prefix + "  ", current_path)
        except Exception as e:
            print(f"{prefix}[Error: {e}]")

# Navigate to Page3
def navigate_to_page3(fields):
    """Navigate to Page3 fields"""
    for field in fields:
        if hasattr(field, 'T') and "Page3" in str(field.T):
            if hasattr(field, 'Kids'):
                explore_page3_fields(field.Kids, "", "Page3")
                return

navigate_to_page3(pdf.Root.AcroForm.Fields)
