import pikepdf

pdf = pikepdf.open('/root/sc100-blank.pdf')

# Find all checkbox fields on Page3
def find_checkboxes_page3(fields, depth=0):
    """Find all checkbox fields"""
    if fields is None:
        return

    for field in fields:
        try:
            name = str(field.T).strip("'\"") if hasattr(field, 'T') else ""
            ftype = str(field.FT).strip("'\"") if hasattr(field, 'FT') else ""

            # Only print checkboxes
            if ftype == "/Btn":
                print(f"{'  ' * depth}{name} (Checkbox)")

            if hasattr(field, 'Kids') and field.Kids:
                find_checkboxes_page3(field.Kids, depth + 1)
        except:
            pass

print("All checkbox fields:")
find_checkboxes_page3(pdf.Root.AcroForm.Fields)
